%% =========================================================
% AERIS - NLMS ADAPTIVE NOISE CANCELLATION
% Normalized Least Mean Squares
%
% Uses the SAME test files generated by AERIS_first_test.m
% ==========================================================

clear;
clc;
close all;

fprintf('\n');
fprintf('=================================================\n');
fprintf('       AERIS - NLMS ADAPTIVE NOISE CANCELLER\n');
fprintf('=================================================\n\n');

%% =========================================================
% 1. PROJECT PATHS
% ==========================================================

projectFolder = 'C:\Users\nuppe\Documents\MATLAB\AERIS_SIH';

outputFolder = fullfile(projectFolder,'OUTPUT');

cleanFile = fullfile(outputFolder,'clean_test.wav');
noisyFile = fullfile(outputFolder,'noisy_test.wav');
noiseFile = fullfile(outputFolder,'scaled_noise.wav');

%% =========================================================
% 2. CHECK FILES
% ==========================================================

if ~exist(cleanFile,'file')
    error('Clean audio file not found: %s',cleanFile);
end

if ~exist(noisyFile,'file')
    error('Noisy audio file not found: %s',noisyFile);
end

if ~exist(noiseFile,'file')
    error('Reference noise file not found: %s',noiseFile);
end

fprintf('Input files found successfully.\n\n');

%% =========================================================
% 3. LOAD AUDIO
% ==========================================================

[clean,FsClean] = audioread(cleanFile);
[noisy,FsNoisy] = audioread(noisyFile);
[referenceNoise,FsNoise] = audioread(noiseFile);

%% =========================================================
% 4. CONVERT STEREO TO MONO
% ==========================================================

if size(clean,2) > 1
    clean = mean(clean,2);
end

if size(noisy,2) > 1
    noisy = mean(noisy,2);
end

if size(referenceNoise,2) > 1
    referenceNoise = mean(referenceNoise,2);
end

%% =========================================================
% 5. CHECK SAMPLING RATES
% ==========================================================

fprintf('Clean sampling rate     : %d Hz\n',FsClean);
fprintf('Noisy sampling rate     : %d Hz\n',FsNoisy);
fprintf('Reference noise rate    : %d Hz\n\n',FsNoise);

if FsClean ~= FsNoisy
    error('Clean and noisy signals have different sampling rates.');
end

if FsClean ~= FsNoise
    fprintf('Resampling reference noise...\n');

    referenceNoise = resample( ...
        referenceNoise,FsClean,FsNoise);

end

Fs = FsClean;

%% =========================================================
% 6. MATCH SIGNAL LENGTHS
% ==========================================================

N = min([ ...
    length(clean), ...
    length(noisy), ...
    length(referenceNoise)]);

clean = clean(1:N);
noisy = noisy(1:N);
referenceNoise = referenceNoise(1:N);

clean = clean(:);
noisy = noisy(:);
referenceNoise = referenceNoise(:);

fprintf('Number of samples       : %d\n',N);
fprintf('Signal duration         : %.2f seconds\n\n',N/Fs);

%% =========================================================
% 7. NLMS PARAMETERS
% ==========================================================

filterOrder = 32;

% NLMS normalized step size
mu = 0.8;

% Small constant to avoid division by zero
epsilon = 1e-8;

fprintf('NLMS filter order       : %d\n',filterOrder);
fprintf('NLMS step size (mu)     : %.2f\n',mu);
fprintf('Regularization epsilon  : %.1e\n\n',epsilon);

%% =========================================================
% 8. INITIALIZE NLMS
% ==========================================================

weights = zeros(filterOrder,1);

estimatedNoise = zeros(N,1);

enhanced = zeros(N,1);

xBuffer = zeros(filterOrder,1);

%% =========================================================
% 9. NLMS ADAPTIVE FILTER
% ==========================================================

fprintf('Running NLMS adaptive noise cancellation...\n');

for n = 1:N

    % ------------------------------------------------------
    % Update reference-noise input buffer
    % ------------------------------------------------------

    xBuffer = [referenceNoise(n); xBuffer(1:end-1)];

    % ------------------------------------------------------
    % Estimate noise
    % ------------------------------------------------------

    estimatedNoise(n) = weights' * xBuffer;

    % ------------------------------------------------------
    % Error signal
    %
    % desired signal = noisy speech
    % estimated noise = adaptive filter output
    % enhanced signal = error
    % ------------------------------------------------------

    enhanced(n) = noisy(n) - estimatedNoise(n);

    % ------------------------------------------------------
    % Calculate input power
    % ------------------------------------------------------

    inputPower = xBuffer' * xBuffer;

    % ------------------------------------------------------
    % NLMS weight update
    % ------------------------------------------------------

    weights = weights + ...
        (mu / (epsilon + inputPower)) ...
        * enhanced(n) * xBuffer;

end

fprintf('NLMS processing complete.\n\n');

%% =========================================================
% 10. REMOVE DC OFFSET
% ==========================================================

enhanced = enhanced - mean(enhanced);

%% =========================================================
% 11. PREVENT CLIPPING
% ==========================================================

maxValue = max(abs(enhanced));

if maxValue > 0.99

    enhanced = enhanced * (0.99 / maxValue);

end

%% =========================================================
% 12. CALCULATE INPUT SNR
% ==========================================================

inputError = noisy - clean;

inputSNR = ...
    10 * log10( ...
    sum(clean.^2) / ...
    sum(inputError.^2));

%% =========================================================
% 13. CALCULATE OUTPUT SNR
% ==========================================================

outputError = enhanced - clean;

outputSNR = ...
    10 * log10( ...
    sum(clean.^2) / ...
    sum(outputError.^2));

%% =========================================================
% 14. SNR IMPROVEMENT
% ==========================================================

snrImprovement = outputSNR - inputSNR;

%% =========================================================
% 15. CALCULATE MSE
% ==========================================================

inputMSE = mean((clean - noisy).^2);

outputMSE = mean((clean - enhanced).^2);

%% =========================================================
% 16. DISPLAY RESULTS
% ==========================================================

fprintf('=================================================\n');
fprintf('                AERIS NLMS RESULTS\n');
fprintf('=================================================\n\n');

fprintf('Input SNR        : %.2f dB\n',inputSNR);
fprintf('Output SNR       : %.2f dB\n',outputSNR);
fprintf('SNR Improvement  : %.2f dB\n\n',snrImprovement);

fprintf('Input MSE        : %.8f\n',inputMSE);
fprintf('Output MSE       : %.8f\n\n',outputMSE);

%% =========================================================
% 17. SAVE ENHANCED SPEECH
% ==========================================================

enhancedFile = ...
    fullfile(outputFolder,'NLMS_enhanced_speech.wav');

audiowrite(enhancedFile,enhanced,Fs);

fprintf('NLMS enhanced speech saved:\n');
fprintf('%s\n\n',enhancedFile);

%% =========================================================
% 18. SAVE ESTIMATED NOISE
% ==========================================================

estimatedNoiseFile = ...
    fullfile(outputFolder,'NLMS_estimated_noise.wav');

audiowrite(estimatedNoiseFile, ...
    estimatedNoise,Fs);

fprintf('NLMS estimated noise saved:\n');
fprintf('%s\n\n',estimatedNoiseFile);

%% =========================================================
% 19. SAVE RESULTS TO TEXT FILE
% ==========================================================

resultsFile = ...
    fullfile(outputFolder,'NLMS_results.txt');

fid = fopen(resultsFile,'w');

fprintf(fid,'AERIS NLMS ADAPTIVE NOISE CANCELLATION RESULTS\n');
fprintf(fid,'===============================================\n\n');

fprintf(fid,'Sampling Rate       : %d Hz\n',Fs);
fprintf(fid,'Filter Order        : %d\n',filterOrder);
fprintf(fid,'Step Size           : %.4f\n',mu);

fprintf(fid,'Input SNR           : %.4f dB\n',inputSNR);
fprintf(fid,'Output SNR          : %.4f dB\n',outputSNR);
fprintf(fid,'SNR Improvement     : %.4f dB\n',snrImprovement);

fprintf(fid,'Input MSE           : %.10f\n',inputMSE);
fprintf(fid,'Output MSE          : %.10f\n',outputMSE);

fclose(fid);

%% =========================================================
% 20. TIME AXIS
% ==========================================================

t = (0:N-1) / Fs;

%% =========================================================
% 21. PLOT 1 - CLEAN SPEECH
% ==========================================================

figure;

plot(t,clean);

xlabel('Time (seconds)');
ylabel('Amplitude');

title('Original Clean Speech');

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_01_clean.png'));

%% =========================================================
% 22. PLOT 2 - NOISY SPEECH
% ==========================================================

figure;

plot(t,noisy);

xlabel('Time (seconds)');
ylabel('Amplitude');

title(sprintf( ...
    'Noisy Speech - Input SNR = %.2f dB', ...
    inputSNR));

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_02_noisy.png'));

%% =========================================================
% 23. PLOT 3 - ESTIMATED NOISE
% ==========================================================

figure;

plot(t,estimatedNoise);

xlabel('Time (seconds)');
ylabel('Amplitude');

title('NLMS Estimated Noise');

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_03_estimated_noise.png'));

%% =========================================================
% 24. PLOT 4 - ENHANCED SPEECH
% ==========================================================

figure;

plot(t,enhanced);

xlabel('Time (seconds)');
ylabel('Amplitude');

title(sprintf( ...
    'NLMS Enhanced Speech - Output SNR = %.2f dB', ...
    outputSNR));

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_04_enhanced.png'));

%% =========================================================
% 25. PLOT 5 - NOISY VS ENHANCED
% ==========================================================

figure;

plot(t,noisy);

hold on;

plot(t,enhanced);

xlabel('Time (seconds)');
ylabel('Amplitude');

title('AERIS NLMS - Noisy vs Enhanced');

legend('Noisy Speech','NLMS Enhanced Speech');

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_05_comparison.png'));

%% =========================================================
% 26. FFT - CLEAN
% ==========================================================

L = length(clean);

Yclean = fft(clean);

P2clean = abs(Yclean/L);

P1clean = P2clean(1:floor(L/2)+1);

P1clean(2:end-1) = ...
    2 * P1clean(2:end-1);

f = Fs * ...
    (0:floor(L/2)) / L;

%% =========================================================
% 27. FFT - NOISY
% ==========================================================

Ynoisy = fft(noisy);

P2noisy = abs(Ynoisy/L);

P1noisy = ...
    P2noisy(1:floor(L/2)+1);

P1noisy(2:end-1) = ...
    2 * P1noisy(2:end-1);

%% =========================================================
% 28. FFT - ENHANCED
% ==========================================================

Yenhanced = fft(enhanced);

P2enhanced = abs(Yenhanced/L);

P1enhanced = ...
    P2enhanced(1:floor(L/2)+1);

P1enhanced(2:end-1) = ...
    2 * P1enhanced(2:end-1);

%% =========================================================
% 29. FFT COMPARISON
% ==========================================================

figure;

plot(f,P1clean);

hold on;

plot(f,P1noisy);

plot(f,P1enhanced);

xlabel('Frequency (Hz)');
ylabel('Magnitude');

title('AERIS NLMS Frequency Spectrum');

legend('Clean','Noisy','NLMS Enhanced');

xlim([0 8000]);

grid on;

saveas(gcf, ...
    fullfile(outputFolder,'NLMS_06_FFT_comparison.png'));

%% =========================================================
% 30. FINAL MESSAGE
% ==========================================================

fprintf('=================================================\n');
fprintf('          AERIS NLMS TEST COMPLETE\n');
fprintf('=================================================\n\n');

fprintf('Input SNR        : %.2f dB\n',inputSNR);
fprintf('Output SNR       : %.2f dB\n',outputSNR);
fprintf('SNR Improvement  : %.2f dB\n',snrImprovement);

fprintf('\nInput MSE        : %.8f\n',inputMSE);
fprintf('Output MSE       : %.8f\n\n',outputMSE);

fprintf('Generated files are inside:\n');
fprintf('%s\n\n',outputFolder);

fprintf('NEXT STEP:\n');
fprintf('Compare LMS vs NLMS.\n');

fprintf('\n=================================================\n');